import pytestfrom src.generators import filter_by_currency, transaction_descriptions, card_number_generator# позитивный тест filter_by_currency -> 100% PASSEDdef test_filter_by_currency(positive_filter_by_currency, positive_filter_by_currency_expected_values):    for _ in range(positive_filter_by_currency.count('"code": "USD"')):        assert list(next(filter_by_currency(positive_filter_by_currency, "USD"))) == \               positive_filter_by_currency_expected_values# негативный тест filter_by_currency -> 100% PASSEDdef test_filter_by_currency_negative(negative_filter_by_currency):    with pytest.raises(Exception):        assert filter_by_currency(negative_filter_by_currency, "USD")# позитивный тест transaction_descriptions -> 100% PASSEDdef test_transaction_descriptions(positive_transaction_descriptions, positive_transaction_descriptions_expected):    for _ in range(positive_transaction_descriptions.count("description")):        assert list(next(transaction_descriptions(positive_transaction_descriptions))) == \               positive_transaction_descriptions_expected# негативный тест transaction_descriptions -> 100% PASSEDdef test_transaction_descriptions_negative(negative_transaction_descriptions):    with pytest.raises(Exception):        assert next(transaction_descriptions(negative_transaction_descriptions))# параметризация с позитивными и негативными сценариями для функции card_number_generator -> 100% PASSED@pytest.mark.parametrize("start, end, expected", [    (0, 1, ['Неверные входные данные', 'Неверные входные данные', '0000 0000 0000 0001']),    (-1, -10, ["Неверные входные данные"]),    (0, -10, ["Неверные входные данные"]),    (9999, 10000, ['0000 0000 0000 9999', '0000 0000 0001 0000']),])def test_card_number_generator(start, end, expected):    # print(start, end, expected)    assert list(card_number_generator(start, end)) == expectedif __name__ == '__main__':    pytest.main(['-vv'])